const CATALOG_BY_SLUG = new Map(GYM_CATALOG.map((g) => [g.slug, g]));
const NETWORK_SET = new Set(
  GYM_CATALOG.filter((g) => !g.independent).map((g) => g.brand)
);

export function gymFacilityId(slug: string): string {
  return `gym_${slug}`;
}

export function catalogAsPublicGyms(): {
  id: string;
  name: string;
  slug: string;
  city: string;
  brand: string;
  independent: boolean;
}[] {
  return GYM_CATALOG.map((g) => ({
    id: gymFacilityId(g.slug),
    name: g.name,
    slug: g.slug,
    city: "Singapore",
    brand: g.brand,
    independent: g.independent,
  }));
}

export function catalogFacilityRow(entry: GymCatalogEntry) {
  return {
    id: gymFacilityId(entry.slug),
    name: entry.name,
    slug: entry.slug,
    brand: entry.brand,
    city: "Singapore",
    region: entry.region,
    country: "SG",
    lat: entry.lat,
    lng: entry.lng,
  };
}

export function gymCatalogEntry(slug: string): GymCatalogEntry | undefined {
  return CATALOG_BY_SLUG.get(slug);
}

export function gymIsIndependent(g: {
  slug: string;
  brand?: string | null;
  independent?: boolean;
}): boolean {
  return gymNetworkOf(g) === INDEPENDENT_NETWORK;
}

/** Chain name, or Independent / boutique for single-studio gyms. */
export function gymNetworkOf(g: {
  slug: string;
  brand?: string | null;
  independent?: boolean;
}): string {
  if (g.independent === true) return INDEPENDENT_NETWORK;
  const cat = CATALOG_BY_SLUG.get(g.slug);
  if (cat) return cat.independent ? INDEPENDENT_NETWORK : cat.brand;
  const brand = (g.brand || "").trim();
  if (brand && NETWORK_SET.has(brand)) return brand;
  return INDEPENDENT_NETWORK;
}

export function gymOutletLabel(g: {
  name: string;
  slug: string;
  brand?: string | null;
}): string {
  const cat = CATALOG_BY_SLUG.get(g.slug);
  if (cat) return cat.independent ? cat.name : cat.outlet;
  const brand = (g.brand || "").trim();
  if (brand && g.name.startsWith(`${brand} `)) return g.name.slice(brand.length + 1);
  return g.name;
}

export function gymCatalogNetworks(): string[] {
  return [...NETWORK_SET].sort((a, b) => a.localeCompare(b));
}

export function listGymNetworks(
  gyms: { slug: string; brand?: string | null; independent?: boolean }[]
): string[] {
  const nets = new Set<string>();
  let hasIndep = false;
  for (const g of gyms) {
    const n = gymNetworkOf(g);
    if (n === INDEPENDENT_NETWORK) hasIndep = true;
    else nets.add(n);
  }
  const sorted = [...nets].sort((a, b) => a.localeCompare(b));
  return hasIndep ? [INDEPENDENT_NETWORK, ...sorted] : sorted;
}

export function gymsInNetwork<
  T extends { slug: string; brand?: string | null; independent?: boolean },
>(gyms: T[], network: string): T[] {
  if (!network) return gyms;
  return gyms.filter((g) => gymNetworkOf(g) === network);
}

export function gymsForNetwork(network: string): GymCatalogEntry[] {
  if (network === INDEPENDENT_NETWORK) {
    return GYM_CATALOG.filter((g) => g.independent).sort((a, b) =>
      a.name.localeCompare(b.name)
    );
  }
  return GYM_CATALOG.filter((g) => !g.independent && g.brand === network).sort(
    (a, b) => a.outlet.localeCompare(b.outlet)
  );
}

